<?php
require_once __DIR__ . '/../../cors.php';require_once __DIR__ . '/../../db/db.php';require_once __DIR__ . '/../../reusables/platform_guard.php';header('Content-Type: application/json');requirePlatformExecutive($pdo,'oversight.emergency_requests.read');
try{$items=$pdo->query("SELECT a.id,a.unit_code,a.plate_number,a.ambulance_type,a.status,a.last_location_at,a.registration_expiry,a.inspection_expiry,o.id organization_id,o.name organization_name,(SELECT rc.overall_status FROM ambulance_readiness_checks rc WHERE rc.ambulance_id=a.id ORDER BY rc.created_at DESC LIMIT 1) readiness_status,(SELECT rc.created_at FROM ambulance_readiness_checks rc WHERE rc.ambulance_id=a.id ORDER BY rc.created_at DESC LIMIT 1) readiness_at FROM ambulances a JOIN organizations o ON o.id=a.organization_id WHERE a.deleted_at IS NULL AND o.deleted_at IS NULL AND o.application_status='approved' ORDER BY o.name,a.unit_code")->fetchAll(PDO::FETCH_ASSOC);$stats=['total'=>count($items),'available'=>0,'active_mission'=>0,'maintenance'=>0,'ready'=>0];foreach($items as &$i){$i['id']=(int)$i['id'];if($i['status']==='available')$stats['available']++;if(in_array($i['status'],['reserved','dispatched','on_scene','transporting','returning'],true))$stats['active_mission']++;if(in_array($i['status'],['maintenance','offline'],true))$stats['maintenance']++;if($i['readiness_status']==='ready')$stats['ready']++;}unset($i);echo json_encode(['success'=>true,'items'=>$items,'stats'=>$stats]);}catch(Throwable $e){error_log('Platform fleet oversight failed: '.$e->getMessage());platformJsonError(500,'Unable to load city-wide fleet availability.');}
